with latest as (select * from (select *, row_number() over (partition by txn_type order by amount nulls last, id) as rn from transactions) x where rn = 1) select case when amount >= 3900 then 'PREMIUM' else 'STANDARD' end as amount_tier, txn_type, count_if(merchant = '7-Eleven') as 7_eleven_events, count(*) as event_count, min(txn_time) as started_at, round(avg(amount), 2) as avg_amount, round(sum(amount) / nullif(count(case when merchant = 'Amazon' then 1 end), 0), 2) as amount_per_amazon, (unix_timestamp(max(txn_time)) - unix_timestamp(min(txn_time))) / 60 as span_minutes from latest group by 1, 2 having avg_amount >= 0
